/**
 * Helper to trigger automatic download of Excel file in the client browser
 * using the Base64 payload generated by the backend exporter.
 */
export function triggerBrowserExcelDownload(excelDownload) {
  if (!excelDownload || !excelDownload.fileBase64) {
    return false;
  }

  try {
    const byteCharacters = atob(excelDownload.fileBase64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    });

    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.style.display = 'none';
    a.href = url;
    a.download = excelDownload.fileName || 'exam_marks.xlsx';
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);
    }, 200);

    return true;
  } catch (err) {
    console.warn('[ExcelHelper] Could not auto-download file in browser:', err);
    return false;
  }
}

